import '../../domain/entities/starting_baseline.dart';
class StartingBaselineModel { const StartingBaselineModel(this.json); final Map<String,dynamic> json; StartingBaseline toEntity()=>StartingBaseline(requirement:json['requirement'] as String? ?? 'OPTIONAL',status:json['status'] as String? ?? 'NOT_STARTED',baselineId:json['baselineId'] as String?,startingWeightKg:(json['startingWeightKg'] as num?)?.toDouble(),completedAt:json['completedAt'] is String?DateTime.tryParse(json['completedAt'] as String):null,photos:((json['photos'] as List?)??const[]).map((e){final m=Map<String,dynamic>.from(e as Map);return StartingBaselinePhoto(id:m['id'] as String,angle:switch(m['angle']){'SIDE'=>BaselineAngle.side,'BACK'=>BaselineAngle.back,_=>BaselineAngle.front},uploadConfirmed:m['uploadConfirmed'] as bool? ?? false);}).toList()); }
